// import AOS from "aos";
import "aos/dist/aos.css";
import { FaBullhorn, FaGlobe, FaPaintBrush, FaPenNib, FaChartLine, FaWhatsapp } from "react-icons/fa";
import { Client1, Client2, Client3, Client4 } from "../../asset/image";

function Advertising() {
    //-----------------------STATE VIEWS-----------------------//
    const advertisingServices = [
        {
            title: "Advertising Website",
            description: "Pembuatan dan pengelolaan website promosi yang efektif dan berorientasi konversi.",
            icon: FaGlobe,
        },
        {
            title: "Design",
            description: "Desain visual profesional untuk kebutuhan branding dan materi promosi.",
            icon: FaPaintBrush,
        },
        {
            title: "Copywriting",
            description: "Penulisan konten persuasif yang memperkuat pesan dan identitas brand.",
            icon: FaPenNib,
        },
        {
            title: "Digital Marketing",
            description: "Strategi pemasaran digital terintegrasi untuk meningkatkan jangkauan dan performa bisnis.",
            icon: FaChartLine,
        },
    ];
    const clients = [
        { name: "Client 1", logo: Client1 },
        { name: "Client 2", logo: Client2 },
        { name: "Client 3", logo: Client3 },
        { name: "Client 4", logo: Client4 },
    ];
    const WA_NUMBER = "6281213094426";
    //-----------------------STATE VIEWS-----------------------//

    //------------------------FUNCTIONS------------------------// 
    const getWaLink = (serviceName: string) => {
        const message = `Halo Regarde,%0ASaya ingin bertanya lebih lanjut mengenai layanan ${serviceName}.%0AMohon informasinya. Terima kasih.`;
        return `https://wa.me/${WA_NUMBER}?text=${message}`;
    };
    //------------------------FUNCTIONS------------------------// 

    return (
        <div className="pt-24">
            {/* ADVERTISING DETAIL */}
            <section className="pb-24 bg-white" data-aos="zoom-out">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-sky-100 flex items-center justify-center">
                            <FaBullhorn className="text-sky-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-sky-900 mb-4">
                        Advertising
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        Layanan periklanan terpadu untuk membantu brand membangun identitas,
                        meningkatkan visibilitas, dan menjangkau audiens secara efektif.
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {advertisingServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-sky-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-sky-900">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className=" mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition "
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>

                            );
                        })}
                    </div>

                </div>
            </section>

            {/* OUR CLIENTS */}
            <section className="py-20">
                <div className="w-11/12 md:w-9/12 mx-auto text-center">
                    <h2
                        data-aos="zoom-in"
                        className="text-center text-4xl font-black text-sky-900 mb-12"
                    >
                        Our Clients
                    </h2>
                    <div className="flex flex-wrap justify-center gap-8">
                        {clients.map((client, i) => (
                            <div
                                key={i}
                                data-aos="fade-up"
                                data-aos-delay={i * 40}
                                className="flex items-center justify-center"
                            >
                                <img
                                    src={client.logo}
                                    alt={client.name}
                                    className="h-10 md:h-12 object-contain opacity-90 hover:opacity-100 transition"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default Advertising;
